    template=[(r,c,g[r][c]) for r,c in pts if g[r][c] not in (bg,6)]
    if not template: return g
    # A row/column template is located at the far edge; reproduce its ordered sequence.
    rows=sorted(set(r for r,c,v in template)); cols=sorted(set(c for r,c,v in template))
    if len(cols)==1:
        vals=[g[r][cols[0]] for r in rows]
        mid=len(vals)//2
        for r,row in enumerate(g):
            for c,v in enumerate(row):
                if v==6:
                    for i,x in enumerate(vals):
                        rr=r+i-mid
                        if 0<=rr<len(g): g[rr][c]=x
    else:
        vals=[g[rows[0]][c] for c in cols]
        mid=len(vals)//2
